    a_valid = [interval for interval in a if interval[0] < interval[1]]
    b_valid = [interval for interval in b if interval[0] < interval[1]]

    if not a_valid:
        return []

    if not b_valid:
        return sorted(a_valid)

    # Merge intervals in a to get the union of a
    a_sorted = sorted(a_valid)
    a_merged = []
    for start, end in a_sorted:
        if a_merged and start <= a_merged[-1][1]:
            a_merged[-1][1] = max(a_merged[-1][1], end)
        else:
            a_merged.append([start, end])

    # Merge intervals in b to get the union of b
    b_sorted = sorted(b_valid)
    b_merged = []
    for start, end in b_sorted:
        if b_merged and start <= b_merged[-1][1]:
            b_merged[-1][1] = max(b_merged[-1][1], end)
        else:
            b_merged.append([start, end])

    # Subtract b from a
    result = []
    for a_start, a_end in a_merged:
        current_ranges = [[a_start, a_end]]

        for b_start, b_end in b_merged:
            new_ranges = []
            for curr_start, curr_end in current_ranges:
                # No overlap
                if curr_end <= b_start or curr_start >= b_end:
                    new_ranges.append([curr_start, curr_end])
                else:
                    # There is overlap, keep the parts not covered by b
                    if curr_start < b_start:
                        new_ranges.append([curr_start, b_start])
                    if curr_end > b_end:
                        new_ranges.append([b_end, curr_end])
            current_ranges = new_ranges

        result.extend(current_ranges)

    # Merge touching intervals in result
    result.sort()
    merged_result = []
    for start, end in result:
        if merged_result and start <= merged_result[-1][1]:
            merged_result[-1][1] = max(merged_result[-1][1], end)
        else:
            merged_result.append([start, end])

    return merged_result

